namespace RonSijm.FluidHumidifier.Factories.IoT;

public class OTAUpdateFactory(string resourceName = null, Action<Humidifier.IoT.OTAUpdate> factoryAction = null) : ResourceFactory<Humidifier.IoT.OTAUpdate>(resourceName)
{

    internal List<InnerOTAUpdateOTAUpdateFileFactory> FilesFactories { get; set; } = [];

    internal InnerOTAUpdateAwsJobTimeoutConfigFactory AwsJobTimeoutConfigFactory { get; set; }

    internal InnerOTAUpdateAwsJobAbortConfigFactory AwsJobAbortConfigFactory { get; set; }

    internal InnerOTAUpdateAwsJobPresignedUrlConfigFactory AwsJobPresignedUrlConfigFactory { get; set; }

    internal InnerOTAUpdateAwsJobExecutionsRolloutConfigFactory AwsJobExecutionsRolloutConfigFactory { get; set; }

    protected override Humidifier.IoT.OTAUpdate Create()
    {
        var oTAUpdateResult = CreateOTAUpdate();
        factoryAction?.Invoke(oTAUpdateResult);

        return oTAUpdateResult;
    }

    private Humidifier.IoT.OTAUpdate CreateOTAUpdate()
    {
        var oTAUpdateResult = new Humidifier.IoT.OTAUpdate
        {
            GivenName = InputResourceName,
        };

        return oTAUpdateResult;
    }
    public override void CreateChildren(Humidifier.IoT.OTAUpdate result)
    {
        base.CreateChildren(result);

        result.Files = FilesFactories.Any() ? FilesFactories.Select(x => x.Build()).ToList() : null;
        result.AwsJobTimeoutConfig ??= AwsJobTimeoutConfigFactory?.Build();
        result.AwsJobAbortConfig ??= AwsJobAbortConfigFactory?.Build();
        result.AwsJobPresignedUrlConfig ??= AwsJobPresignedUrlConfigFactory?.Build();
        result.AwsJobExecutionsRolloutConfig ??= AwsJobExecutionsRolloutConfigFactory?.Build();
    }

} // End Of Class

